function isAuthPage(){const p=window.location.pathname;return"/"===p||""===p||p.endsWith("/index.php")||"/login"===p||"/login/"===p||"/signin"===p||"/signin/"===p||"/register"===p||"/register/"===p||"/signup"===p||"/signup/"===p}if(window.currentUser)try{localStorage.setItem("ptolemy_user",JSON.stringify(window.currentUser))}catch(e){}else if(isAuthPage())localStorage.removeItem("ptolemy_user");else{const cachedUser=localStorage.getItem("ptolemy_user");if(cachedUser)try{window.currentUser=JSON.parse(cachedUser)}catch(e){localStorage.removeItem("ptolemy_user")}}async function handleLogin(email,password){try{const cleanIdent=(email||"").trim(),response=await fetch("/api/auth.php?action=login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({identifier:cleanIdent,email:cleanIdent,username:cleanIdent,password:password})}),data=await response.json();if(!response.ok)throw new Error(data.error||"Login failed.");window.currentUser=data,localStorage.setItem("ptolemy_user",JSON.stringify(data)),window.location.href="/dashboard/"}catch(err){throw console.error("Login error:",err),err}}async function handleRegister(email,password,passwordConfirm,inviteToken,name){try{const response=await fetch("/api/auth.php?action=register",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:email,password:password,passwordConfirm:passwordConfirm,inviteToken:inviteToken,name:name})}),data=await response.json();if(!response.ok)throw new Error(data.error||"Registration failed.");window.currentUser=data,localStorage.setItem("ptolemy_user",JSON.stringify(data)),window.location.href="/dashboard/"}catch(err){throw console.error("Registration error:",err),err}}async function logout(){try{await fetch("/api/auth.php?action=logout",{method:"POST"})}catch(err){console.error("Logout API error:",err)}window.currentUser=null,localStorage.removeItem("ptolemy_user"),window.location.href="/"}function checkAuth(){window.currentUser||isAuthPage()||(window.location.href="/login")}function initPasswordToggles(){document.querySelectorAll(".toggle-password-btn").forEach(btn=>{btn.addEventListener("click",e=>{e.preventDefault();const targetId=btn.getAttribute("data-target"),input=document.getElementById(targetId);if(!input)return;const icon=btn.querySelector("i");"password"===input.type?(input.type="text",btn.setAttribute("aria-label","Hide password"),icon&&(icon.classList.remove("bi-eye"),icon.classList.add("bi-eye-slash"))):(input.type="password",btn.setAttribute("aria-label","Show password"),icon&&(icon.classList.remove("bi-eye-slash"),icon.classList.add("bi-eye")))})})}document.addEventListener("DOMContentLoaded",()=>{initPasswordToggles();const isIndex=isAuthPage();window.currentUser&&fetch("/api/auth.php?action=me").then(res=>{res.ok?res.json().then(user=>{window.currentUser=user,localStorage.setItem("ptolemy_user",JSON.stringify(user));const emailEl=document.getElementById("user-email");emailEl&&(emailEl.textContent=user.email||user.username);const adminLink=document.getElementById("admin-nav-link");adminLink&&user.is_admin&&adminLink.classList.remove("d-none"),isIndex&&(window.location.href="/dashboard/")}):(window.currentUser=null,localStorage.removeItem("ptolemy_user"),isIndex||(window.location.href="/"))}).catch(()=>{window.currentUser=null,localStorage.removeItem("ptolemy_user"),isIndex||(window.location.href="/")});const loginForm=document.getElementById("login-form"),registerForm=document.getElementById("register-form"),errorAlert=document.getElementById("error-alert"),errorMessage=document.getElementById("error-message");if(console.log("auth.js diagnostics:",{isIndex:isIndex,pathname:window.location.pathname,loginForm:loginForm?"found":"missing",registerForm:registerForm?"found":"missing"}),isIndex&&loginForm&&registerForm){const invite=new URLSearchParams(window.location.search).get("invite");if(invite){const inviteInput=document.getElementById("reg-invite");inviteInput&&(inviteInput.value=invite);const registerTab=document.getElementById("register-tab");registerTab&&bootstrap.Tab.getOrCreateInstance(registerTab).show()}function showError(message){errorMessage&&errorAlert&&(errorMessage.textContent=message,errorAlert.style.display="block")}function hideError(){errorAlert&&(errorAlert.style.display="none")}function setSubmitting(btnId,isSubmitting){const btn=document.getElementById(btnId);if(!btn)return;const text=btn.querySelector(".btn-text"),spinner=btn.querySelector(".loading-spinner");isSubmitting?(btn.disabled=!0,text&&(text.style.display="none"),spinner&&(spinner.style.display="inline-block")):(btn.disabled=!1,text&&(text.style.display="inline"),spinner&&(spinner.style.display="none"))}loginForm.addEventListener("submit",async e=>{e.preventDefault(),hideError(),setSubmitting("login-btn",!0);const email=document.getElementById("login-email").value.trim(),password=document.getElementById("login-password").value;try{await handleLogin(email,password)}catch(err){showError(err.message||"Failed to login. Please check your credentials."),setSubmitting("login-btn",!1)}}),registerForm.addEventListener("submit",async e=>{e.preventDefault(),hideError();const name=document.getElementById("reg-name").value.trim(),email=document.getElementById("reg-email").value,password=document.getElementById("reg-password").value,passwordConfirm=document.getElementById("reg-password-confirm").value,inviteToken=document.getElementById("reg-invite").value.trim();if(password===passwordConfirm){setSubmitting("register-btn",!0);try{await handleRegister(email,password,passwordConfirm,inviteToken,name)}catch(err){showError(err.message||"Failed to create account."),setSubmitting("register-btn",!1)}}else showError("Passwords do not match.")}),document.querySelectorAll(".nav-link").forEach(tab=>{tab.addEventListener("shown.bs.tab",hideError)})}});